"""Public legal texts and the exact consent snapshot used by the SMTP handler."""
import hashlib
import html

REVISION = '22 октября 2026 года'


def consent_document(site):
    text = f'''Согласие на обработку персональных данных
Редакция: {REVISION}.

Я свободно, своей волей и в своём интересе даю согласие на обработку моих персональных данных, указанных в форме на {site['domain']}/. Оператор: {site['legalName']} (ИНН {site['inn']}, ОГРН {site['ogrn']}, адрес: {site['legalAddress']}).

Цель: ответ на моё обращение, обсуждение потребности в оборудовании, подбор комплектации, подготовка технических требований и индивидуального предложения, согласование возможной поставки.

Данные: имя и телефон; если я их указываю — электронная почта, организация, сведения обо мне в описании задачи и прикреплённом файле. Согласие относится к моим данным; оно не даёт права передавать сведения о других людях без законного основания.

Действия: сбор, запись, систематизация, накопление, хранение, уточнение, извлечение, использование для ответа, предоставление доступа уполномоченным работникам и привлечённым для обработки заявки провайдерам хостинга REG.RU и почты Mail.ru, блокирование, удаление и уничтожение. Обработка выполняется с использованием средств автоматизации и без них. Содержание заявки направляется на {site['email']}. Публикация данных в открытом доступе и использование для рекламных рассылок в это согласие не входят.

Согласие действует до завершения рассмотрения обращения, но не более {site['leadRetentionDays']} календарных дней с даты отправки заявки, либо до моего отзыва, если он поступит раньше. После прекращения обработки данные удаляются в течение 30 дней, если отсутствует самостоятельное законное основание для их дальнейшей обработки. При заключении договора необходимые для него сведения обрабатываются на соответствующем законном основании; это не продлевает согласие на неопределённый срок.

Отозвать согласие можно письмом на {site['email']} с темой «Отзыв согласия» или письменным обращением по адресу оператора. Для поиска обращения достаточно указать использованные при отправке контакты; при необходимости оператор проверяет личность заявителя в установленном законом порядке.

Я предоставляю это согласие отдельным действием — отмечаю изначально пустой флажок «Даю согласие на обработку моих персональных данных для ответа на обращение» и отправляю форму. Согласие не объединяется с принятием условий покупки или подпиской на рекламу.
'''
    digest = hashlib.sha256(text.encode('utf-8')).hexdigest()
    return {'version': 'request-2026-10-22-' + digest[:12], 'sha256': digest,
            'text': text, 'form_enabled': bool(site.get('contactFormEnabled', False))}


def privacy_content(site, provider, counter):
    name, address = html.escape(site['legalName']), html.escape(site['legalAddress'])
    email = html.escape(site['email'])
    preview = '' if provider == 'smtp' else '''<p>Эта статическая копия не содержит формы сбора заявок. Обращение можно отправить на основном сайте. Хостинг копии GitHub Pages обрабатывает технические сведения о посещениях по <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" rel="noopener" target="_blank">правилам GitHub</a>; эта копия не используется для хранения заявок.</p>'''
    analytics = ('<p>Яндекс Метрика включается только после отдельного выбора посетителя. Отказ не препятствует отправке обращения. Счётчик получает технические сведения о посещении и действиях на сайте; поля формы и вложения не передаются в события, Вебвизор отключён. Выбор можно изменить в настройках файлов cookie.</p>' if counter else '<p>Счётчики посещаемости и рекламная аналитика отключены. Форма не устанавливает cookie; шрифты, изображения и скрипты загружаются с сайта.</p>')
    return f'''<p class="legal-revision">Редакция от {REVISION}</p>
<h2>Оператор и область действия</h2><p>Оператор — {name}, ИНН {site['inn']}, КПП {site['kpp']}, ОГРН {site['ogrn']}. Адрес: {address}. По вопросам персональных данных: <a href="mailto:{email}">{email}</a>.</p><p>Политика относится к посетителям сайта и людям, которые обращаются за подбором и поставкой оборудования, в том числе представителям организаций. Она описывает обработку обращений и технических сведений о работе сайта.</p>{preview}
<h2>Цели, данные и основания обработки</h2>
<h3>Обращение за подбором оборудования</h3><p>Обрабатываем имя и телефон; по желанию заявителя — электронную почту, организацию, описание задачи и файл. Цели: ответ на обращение, уточнение потребности, подбор комплектации, подготовка технических требований и предложения, согласование поставки. Основание для формы — отдельное <a href="/consent/">согласие</a> по пункту 1 части 1 статьи 6 Федерального закона № 152-ФЗ.</p><p>Не отправляйте паспортные данные, сведения о здоровье, платёжных картах или лишние данные третьих лиц. Специальные категории и биометрические данные через форму не запрашиваются. Если для дальнейшей сделки нужны дополнительные сведения, их состав и основание обработки определяются отдельно.</p>
<h3>Договор и обращения о покупке</h3><p>При заключении и исполнении договора с физическим лицом необходимая обработка основывается на пункте 5 части 1 статьи 6 закона № 152-ФЗ. Исполнение предусмотренных законом обязанностей, в том числе по учёту расчётов и рассмотрению требований покупателей, — на пункте 2 части 1 статьи 6. Для данных представителя организации основание определяется отдельно: договор с организацией сам по себе не является согласием её работника.</p>
<h3>Работоспособность и безопасность сайта</h3><p>При сетевом обращении сервер получает IP-адрес и технические параметры запроса. Хостинг может вести журналы обращений: дата и время, адрес страницы, код ответа и сведения о браузере. Обработчик формы использует защитный токен, хеш IP-адреса, время и статус запроса для защиты от спама и повторной отправки. Основание — законный интерес оператора в защите сайта и обращений при соблюдении прав посетителей, пункт 7 части 1 статьи 6 закона № 152-ФЗ.</p>
<h2>Порядок обработки и получатели</h2><p>Обработка включает сбор, запись, хранение, уточнение, использование, предоставление необходимого доступа, блокирование, удаление и уничтожение. Доступ получают только работники, которым сведения нужны для работы с обращением. Заявка поступает на сервер сайта и передаётся через почтовый сервер на <a href="mailto:{email}">{email}</a>. Сайт размещён в REG.RU. Заявки и вложения хранятся в почтовом ящике Mail.ru; обработчик сайта не создаёт отдельный архив их содержания. На сервере сайта временно обрабатывается загруженный файл, который удаляется после попытки отправки. При поручении обработки провайдеру оператор обеспечивает договорные условия по части 3 статьи 6 закона № 152-ФЗ.</p><p>Сбор персональных данных граждан РФ должен осуществляться с использованием баз данных на территории РФ. Форма не передаёт сведения в FormSubmit или другие зарубежные сервисы сбора заявок. Оператор не публикует заявки и не передаёт их для сторонних рекламных рассылок. Предоставление сведений государственным органам возможно при наличии предусмотренного законом основания.</p>
<h2>Сроки хранения и уничтожение</h2><p>Обращение без заключённого договора обрабатывается до завершения обсуждения, но не более {site['leadRetentionDays']} календарных дней с даты заявки. Если требуется продолжить общение после этого срока, необходимо определить новое законное основание. После достижения цели или отзыва согласия данные удаляются в течение 30 дней при отсутствии другого законного основания. Необходимые договорные, бухгалтерские и иные обязательные документы хранятся в сроки, установленные применимым законодательством; это не означает бессрочное хранение всех заявок.</p><p>Обработчик не ведёт архив содержания заявок. Временное вложение удаляется после попытки отправки; оставшиеся после сбоя файлы старше часа удаляются обслуживанием. Записи ограничения частоты удаляются после часа, состояния повторной отправки — после двух часов при обслуживании обработчика. Полученные письма, вложения, копии на рабочих устройствах и резервные копии входят в установленный оператором порядок хранения и уничтожения. Удаление включает очистку почты и её корзины, доступных рабочих копий; резервные копии изолируются от обычного использования и удаляются по установленному циклу, с соблюдением предельных сроков закона.</p>
<h2>Согласие и ваши права</h2><p>Галочка согласия изначально не отмечена. Для обращения через форму нужно отдельно подтвердить согласие. Отправка обращения не является подпиской на рекламу. Вместе с письмом сохраняются текст и версия согласия, идентификатор и время отправки — для подтверждения полученного согласия.</p><p>Вы вправе получить сведения об обработке и ознакомиться с данными, потребовать их уточнения, блокирования, уничтожения или прекращения обработки в предусмотренных законом случаях, отозвать согласие и обжаловать действия оператора в <a href="https://rkn.gov.ru/" rel="noopener" target="_blank">Роскомнадзоре</a> или суде.</p><p>Направьте обращение на <a href="mailto:{email}">{email}</a> или по адресу оператора. Укажите контакты, использованные в заявке, и суть требования. Подтверждение личности запрашивается только при необходимости и в установленном законом объёме.</p><p>Сведения об обработке предоставляются в течение 10 рабочих дней; мотивированное продление возможно ещё на 5 рабочих дней. Подтверждённые неточные данные исправляются в течение 7 рабочих дней. Требование прекратить обработку исполняется в течение 10 рабочих дней, с предусмотренным законом продлением не более чем на 5 рабочих дней и исключениями статьи 21 закона № 152-ФЗ. При отзыве согласия действуют указанные выше правила прекращения обработки и уничтожения.</p>
<h2>Защита данных</h2><p>Для передачи формы используется HTTPS. Обработчик проверяет источник запроса, защитный токен, обязательные поля, согласие и формат вложения, ограничивает частоту запросов. Конфигурация почты и временное хранилище размещаются вне публичной папки сайта. Содержание заявки не записывается в техническую базу обработчика или хранилище браузера. Организационные меры включают ограничение доступа, назначение ответственных, соблюдение конфиденциальности и рассмотрение обращений субъектов.</p>
<h2 id="cookies">Файлы cookie и аналитика</h2>{analytics}<p>Настройки аналитики доступны по ссылке «Файлы cookie» в подвале. При подключённой аналитике выбор сохраняется в браузере на 180 дней. Обработчик заявки не требует согласия на рекламные или аналитические cookie. Настройки браузера также позволяют управлять сохранёнными данными.</p>
<h2>Изменения политики</h2><p>Актуальная редакция доступна на этой странице. Изменение текста политики не расширяет ранее предоставленное согласие: для новых целей или состава данных требуется соответствующее правовое основание.</p>'''


def buyer_content(site):
    name, address = html.escape(site['legalName']), html.escape(site['legalAddress'])
    returns = html.escape(site['returnsAddress'])
    email, hours = html.escape(site['email']), html.escape(site['workingHours'])
    return f'''<p class="legal-revision">Редакция от {REVISION}</p>
<h2>Продавец</h2><p>{name}. ИНН {site['inn']}, КПП {site['kpp']}, ОГРН {site['ogrn']}. Адрес: {address}. Режим работы: {hours}. Электронная почта: <a href="mailto:{email}">{email}</a>, телефон: <a href="tel:{site['phoneHref']}">{site['phone']}</a>.</p>
<h2>Подбор и оформление покупки</h2><p>Сайт знакомит с направлениями поставок. Отправка обращения означает запрос на подбор и расчёт; она не оформляет заказ, не резервирует товар и не создаёт обязанности оплатить его. Конкретные модель, комплектация, количество, цена в рублях, наличие, срок действия предложения и условия приобретения указываются в индивидуальном предложении до заключения договора.</p><p>До покупки предоставляем сведения о потребительских свойствах, изготовителе и месте изготовления товара, сроке службы и гарантии, если они установлены, правилах эксплуатации и обязательном подтверждении соответствия. При дистанционной продаже товара, подлежащего обязательному подтверждению соответствия, его описание должно содержать ссылку на запись о сертификате или декларации в соответствующем реестре. Включение модели в реестр российской промышленной продукции не заменяет сертификат или декларацию соответствия.</p>
<h2>Оплата и доставка</h2><p>Способ и порядок оплаты, стоимость доставки, адрес, срок и условия передачи товара согласовываются до заключения договора и фиксируются в предложении или договоре. Сайт не принимает платежи и не запрашивает реквизиты банковской карты. Кассовый чек предоставляется в случаях и порядке, установленных Федеральным законом № 54-ФЗ. Расчётный документ банка не заменяет кассовый чек, когда он обязателен.</p><p>Доставка по России и в страны СНГ рассчитывается для конкретного заказа. Возможность доставки в выбранный населённый пункт и дополнительные услуги подтверждаются до оплаты.</p>
<h2>Покупки физическими лицами</h2><p>Если товар приобретается гражданином для личных, семейных, домашних и иных нужд, не связанных с предпринимательской деятельностью, применяются Закон РФ «О защите прав потребителей» и обязательные правила розничной продажи. Условия индивидуального предложения не ограничивают предусмотренные законом права покупателя.</p>
<h3>Отказ от товара надлежащего качества при дистанционной покупке</h3><p>Покупатель вправе отказаться от товара до передачи, а после передачи — в течение семи дней. Если сведения о порядке и сроках возврата не предоставлены в письменной форме при доставке, срок отказа составляет три месяца с передачи. Для возврата должны быть сохранены товарный вид и потребительские свойства. Отсутствие чека само по себе не исключает возможность подтвердить покупку другими доказательствами.</p><p>Исключение — товар надлежащего качества с индивидуально-определёнными свойствами, который может использоваться исключительно приобретающим его покупателем. Сам по себе подбор стандартной комплектации или статус технически сложного товара не означает автоматического запрета дистанционного возврата.</p><p>Об отказе и возврате можно сообщить на <a href="mailto:{email}">{email}</a> или направить письменное требование по адресу: {returns}. Укажите сведения о покупке, товаре и требовании. Возврат возможен дистанционно, в том числе через перевозчика или почту, способом, позволяющим проверить состояние товара при получении. Для уточнения получателя и режима приёма можно связаться с нами; предварительное согласование не является условием осуществления законного права на возврат.</p><p>При отказе от товара надлежащего качества уплаченная сумма возвращается не позднее десяти дней со дня предъявления соответствующего требования, за исключением предусмотренных законом расходов продавца на доставку возвращённого товара от покупателя. Риск транспортировки и расходы на дистанционный возврат такого товара несёт покупатель в соответствии с применимыми правилами.</p>
<h3>Недостатки товара и гарантийные обращения</h3><p>Сообщите о недостатке на <a href="mailto:{email}">{email}</a> или письменно по адресу: {returns}. Укажите товар, дату покупки, описание недостатка и выбранное требование. Требования рассматриваются по статьям 18–24 Закона РФ «О защите прав потребителей»; применяются предусмотренные законом сроки и особенности технически сложных товаров. Обращение к производителю или в сервисный центр не лишает покупателя права предъявить законное требование продавцу.</p>
<h2>Поставки организациям и предпринимателям</h2><p>Для приобретения в предпринимательских целях условия поставки, приёмки, оплаты, гарантии и возврата определяются договором и применимыми нормами гражданского законодательства. Потребительские правила не подменяют условия такого договора.</p>'''
